import NativeprodMenu from './specs/NativeprodMenu';

/**
 * The prodMenu module exposes methods for interacting with the prod Menu in production.
 */
type prodMenuStatic = {
  /**
   * Show the prod Menu.
   */
  show(): void,
};

const prodMenu: prodMenuStatic = {
  show(): void {
    if (__prod__) {
      NativeprodMenu.show?.();
    }
  },
};

export default prodMenu;
